        key: ['React 19, Next.js 16, Vite 8, Tailwind CSS 4, shadcn/ui, TypeScript : la pile moderne (novembre 2026).', 'Vitrine et démo : HTML/CSS/JS ; application : React/Next.js + TypeScript + Tailwind + Supabase.', 'Dernière version stable, doc à jour pour l’IA, versions fixées.'],
        quiz: [{ q: 'Pour une vitrine de restaurant, le plus simple est…', a: ['Next.js + base de données', 'HTML, CSS et JavaScript', 'Une app Expo'], ok: 1, why: 'Moins de pièces = moins de pannes, publication gratuite.' }],
        todo: ['Pour ton fil rouge, écris la pile choisie et pourquoi', 'Va sur ui.shadcn.com et repère 3 composants utiles pour une application', 'Ajoute la pile choisie dans ton CLAUDE.md'],
